55: // Handler validates configuration part of ConfigMaps which are referenced in Shoot resources.
56: type Handler struct {
57: 	APIReader client.Reader
58: 	Client    client.Reader
59: 	Decoder   admission.Decoder
60: 
61: 	ConfigMapPurpose            string
62: 	ConfigMapDataKey            string
63: 	GetConfigMapNameFromShoot   func(shoot *gardencore.Shoot) string
64: 	SkipValidationOnShootUpdate func(shoot, oldShoot *gardencore.Shoot) bool
65: 	AdmitConfig                 func(configRaw string, shootsReferencingConfigMap []*gardencore.Shoot) (int32, error)
66: 
67: 	GetNamespace               func() string
68: 	GetConfigMapNameFromGarden func(garden *operatorv1alpha1.Garden) string
69: 	AdmitGardenConfig          func(configRaw string) (int32, error)
70: }
71: 
72: // Handle validates configuration part of ConfigMaps which are referenced in Shoot resources.
73: func (h *Handler) Handle(ctx context.Context, req admission.Request) admission.Response {
74: 	requestGK := schema.GroupKind{Group: req.Kind.Group, Kind: req.Kind.Kind}
75: 
76: 	switch requestGK {
77: 	case schema.GroupKind{Group: gardencorev1beta1.GroupName, Kind: "Shoot"}:
78: 		return h.admitShoot(ctx, req)
79: 	case schema.GroupKind{Group: operator.GroupName, Kind: "Garden"}:
80: 		return h.admitGarden(ctx, req)
81: 	case schema.GroupKind{Group: corev1.GroupName, Kind: "ConfigMap"}:
82: 		if h.GetConfigMapNameFromShoot != nil {
83: 			return h.admitConfigMapForShoots(ctx, req)
84: 		}
85: 		return h.admitConfigMapForGardens(ctx, req)
86: 	}
87: 
88: 	return admissionwebhook.Allowed("resource is neither of type core.gardener.cloud/v1beta1.Shoot, operator.gardener.cloud/v1alpha1.Garden, nor corev1.ConfigMap")
89: }
90: 
91: // admitGarden validates configuration part of ConfigMaps which are referenced in Garden resources.
92: func (h *Handler) admitGarden(ctx context.Context, request admission.Request) admission.Response {
93: 	garden := &operatorv1alpha1.Garden{}
94: 	if err := runtime.DecodeInto(operatorDecoder, request.Object.Raw, garden); err != nil {
95: 		return admission.Errored(http.StatusInternalServerError, err)
96: 	}
97: 
98: 	if garden.DeletionTimestamp != nil {
99: 		return admissionwebhook.Allowed("garden is already marked for deletion")
100: 	}
101: 
102: 	configMapName := h.GetConfigMapNameFromGarden(garden)
103: 	if configMapName == "" {
104: 		return admissionwebhook.Allowed("no audit policy config map reference found in garden spec")
105: 	}
106: 
107: 	var oldGarden *operatorv1alpha1.Garden
108: 	if request.Operation == admissionv1.Update {
109: 		oldGarden = &operatorv1alpha1.Garden{}
110: 		if err := runtime.DecodeInto(operatorDecoder, request.OldObject.Raw, oldGarden); err != nil {
111: 			return admission.Errored(http.StatusInternalServerError, err)
112: 		}
113: 
114: 		if apiequality.Semantic.DeepEqual(oldGarden.Spec, garden.Spec) {
115: 			return admissionwebhook.Allowed("garden spec was not changed")
116: 		}
117: 	}
118: 
119: 	if oldGarden != nil && h.GetConfigMapNameFromGarden(oldGarden) == configMapName &&
120: 		oldGarden.Spec.VirtualCluster.Kubernetes.Version == garden.Spec.VirtualCluster.Kubernetes.Version {
121: 		return admissionwebhook.Allowed("audit policy config map reference and kubernetes version were not changed")
122: 	}
123: 
124: 	configMap := &corev1.ConfigMap{ObjectMeta: metav1.ObjectMeta{Namespace: h.GetNamespace(), Name: configMapName}}
125: 	if err := h.APIReader.Get(ctx, client.ObjectKeyFromObject(configMap), configMap); err != nil {
126: 		if apierrors.IsNotFound(err) {
127: 			return admission.Errored(http.StatusUnprocessableEntity, fmt.Errorf("referenced ConfigMap %s does not exist: %w", client.ObjectKeyFromObject(configMap), err))
128: 		}
129: 		return admission.Errored(http.StatusInternalServerError, fmt.Errorf("could not retrieve ConfigMap %s: %w", client.ObjectKeyFromObject(configMap), err))
130: 	}
131: 
132: 	configRaw, err := h.rawConfigurationFromConfigMap(configMap.Data)
133: 	if err != nil {
134: 		return admission.Errored(http.StatusUnprocessableEntity, fmt.Errorf("error getting ConfigMap %s: %w", client.ObjectKeyFromObject(configMap), err))
135: 	}
136: 
137: 	if errCode, err := h.AdmitGardenConfig(configRaw); err != nil {
138: 		return admission.Errored(errCode, err)
139: 	}
140: 
141: 	return admissionwebhook.Allowed("referenced configMap is valid")
142: }
143: 
144: func (h *Handler) admitShoot(ctx context.Context, request admission.Request) admission.Response {
145: 	shoot := &gardencore.Shoot{}
146: 	if err := runtime.DecodeInto(gardenCoreDecoder, request.Object.Raw, shoot); err != nil {
147: 		return admission.Errored(http.StatusInternalServerError, err)
148: 	}
149: 
150: 	if shoot.DeletionTimestamp != nil {
151: 		// don't validate shoot if it's already marked for deletion, otherwise gardener-apiserver will deny the user's/
152: 		// controller's request, because we changed the spec
153: 		return admissionwebhook.Allowed("shoot is already marked for deletion")
154: 	}
155: 
156: 	configMapName := h.GetConfigMapNameFromShoot(shoot)
157: 	if configMapName == "" {
158: 		return admissionwebhook.Allowed(fmt.Sprintf("Shoot resource does not specify any %s ConfigMap", h.ConfigMapPurpose))
159: 	}
160: 
161: 	var oldShoot *gardencore.Shoot
162: 	if request.Operation == admissionv1.Update {
163: 		oldShoot = &gardencore.Shoot{}
164: 		if err := runtime.DecodeInto(gardenCoreDecoder, request.OldObject.Raw, oldShoot); err != nil {
165: 			return admission.Errored(http.StatusInternalServerError, err)
166: 		}
167: 
168: 		// skip verification if spec wasn't changed
169: 		// this way we make sure, that users/gardenlet can always annotate/label the shoot if the spec doesn't change
170: 		if apiequality.Semantic.DeepEqual(oldShoot.Spec, shoot.Spec) {
171: 			return admissionwebhook.Allowed("shoot spec was not changed")
172: 		}
173: 	}
174: 
175: 	// `oldConfigMapName` is empty for CREATE shoot requests that specify a ConfigMap reference, hence we can skip the
176: 	// validation.
177: 	// Additionally, we only need to revalidate if the ConfigMap data is compatible with a new Kubernetes version if the
178: 	// version changed.
179: 	if oldShoot != nil &&
180: 		h.GetConfigMapNameFromShoot(oldShoot) == configMapName &&
181: 		oldShoot.Spec.Kubernetes.Version == shoot.Spec.Kubernetes.Version &&
182: 		(h.SkipValidationOnShootUpdate == nil || h.SkipValidationOnShootUpdate(shoot, oldShoot)) {
183: 		return admissionwebhook.Allowed(fmt.Sprintf("Neither %s ConfigMap nor Kubernetes version or other relevant fields were changed", h.ConfigMapPurpose))
184: 	}
185: 
186: 	configMap := &corev1.ConfigMap{ObjectMeta: metav1.ObjectMeta{Namespace: shoot.Namespace, Name: configMapName}}
187: 	if err := h.APIReader.Get(ctx, client.ObjectKeyFromObject(configMap), configMap); err != nil {
188: 		if apierrors.IsNotFound(err) {
189: 			return admission.Errored(http.StatusUnprocessableEntity, fmt.Errorf("referenced %s ConfigMap %s does not exist: %w", h.ConfigMapPurpose, client.ObjectKeyFromObject(configMap), err))
190: 		}
191: 		return admission.Errored(http.StatusInternalServerError, fmt.Errorf("could not retrieve %s ConfigMap %s: %w", h.ConfigMapPurpose, client.ObjectKeyFromObject(configMap), err))
192: 	}
193: 
194: 	configRaw, err := h.rawConfigurationFromConfigMap(configMap.Data)
195: 	if err != nil {
196: 		return admission.Errored(http.StatusUnprocessableEntity, fmt.Errorf("error getting %s from ConfigMap %s: %w", h.ConfigMapPurpose, client.ObjectKeyFromObject(configMap), err))
197: 	}
198: 
199: 	if errCode, err := h.AdmitConfig(configRaw, []*gardencore.Shoot{shoot}); err != nil {
200: 		return admission.Errored(errCode, err)
201: 	}
202: 
203: 	return admissionwebhook.Allowed(fmt.Sprintf("referenced %s is valid", h.ConfigMapPurpose))
204: }
