206: func (h *Handler) admitConfigMapForShoots(ctx context.Context, request admission.Request) admission.Response {
207: 	var (
208: 		newConfigMap = &corev1.ConfigMap{}
209: 		oldConfigMap = &corev1.ConfigMap{}
210: 	)
211: 
212: 	if request.Operation != admissionv1.Update {
213: 		return admissionwebhook.Allowed("operation is not update, nothing to validate")
214: 	}
215: 
216: 	if err := h.Decoder.Decode(request, newConfigMap); err != nil {
217: 		return admission.Errored(http.StatusInternalServerError, err)
218: 	}
